from urllib.parse import urlparse, urlunparse, parse_qsl, urlencode

def apply_rewrite_rules(rules, urls):
    """
    Applies an ordered list of rewrite rules to a list of URLs.
    For each URL, only the first matching rule is applied.
    """
    processed_urls = []

    for url_str in urls:
        parsed = urlparse(url_str)
        matched = False

        for rule in rules:
            match_type = rule.get("match_type")
            match_value = rule.get("match_value")
            action = rule.get("action")
            action_value = rule.get("action_value")

            # --- 1. Evaluate Matching ---
            is_match = False

            if match_type == "path_prefix":
                if parsed.path.startswith(match_value):
                    is_match = True

            elif match_type == "host":
                host = parsed.hostname or ""
                if host == match_value:
                    is_match = True
                elif match_value.startswith("*."):
                    suffix = match_value[1:]  # e.g. ".example.com"
                    # Check if host ends with suffix and has characters before it
                    if host.endswith(suffix) and len(host) > len(suffix):
                        is_match = True

            elif match_type == "query_param":
                query_params = parse_qsl(parsed.query, keep_blank_values=True)
                # Check if any parameter name matches match_value
                if any(k == match_value for k, v in query_params):
                    is_match = True

            # --- 2. Apply Action if Matched ---
            if is_match:
                matched = True

                if action == "block":
                    parsed = None
                    break

                elif action == "strip_prefix":
                    # Remove action_value from the start of the path
                    if parsed.path.startswith(action_value):
                        new_path = parsed.path[len(action_value):]
                        if not new_path:
                            new_path = "/"
                        parsed = parsed._replace(path=new_path)

                elif action == "redirect_host":
                    # Replace host while preserving port if it was part of netloc
                    # urllib's netloc can be "host:port", so we rebuild netloc carefully.
                    port = parsed.port
                    new_host = action_value
                    new_netloc = f"{new_host}:{port}" if port else new_host
                    parsed = parsed._replace(netloc=new_netloc)

                elif action == "add_query_param":
                    # action_value is e.g. "key=value"
                    if "=" in action_value:
                        k, v = action_value.split("=", 1)
                    else:
                        k, v = action_value, ""

                    query_params = parse_qsl(parsed.query, keep_blank_values=True)
                    query_params.append((k, v))
                    new_query = urlencode(query_params)
                    parsed = parsed._replace(query=new_query)

                # Stop after applying the first matching rule
                break

        # --- 3. Finalize URL for output ---
        if not matched:
            processed_urls.append(url_str)
        elif parsed is None:
            processed_urls.append(None)
        else:
            processed_urls.append(urlunparse(parsed))

    return processed_urls
